# Consumed by kubernetes/apps/buildkite/agent-stack-k8s (the controller that
# creates a k8s Job per build step) via `just buildkite sync-secret`.
resource "buildkite_cluster_agent_token" "kubernetes" {
  cluster_id  = buildkite_cluster.sailing.id
  description = "agent-stack-k8s controller (kubernetes/apps/buildkite)"
}
resource "buildkite_cluster" "sailing" {
  name        = var.cluster_name
  description = "Self-hosted agents running on the sailing k8s cluster"
  emoji       = ":kubernetes:"
  color       = "#326ce5"
}

resource "buildkite_cluster_queue" "kubernetes" {
  cluster_id = buildkite_cluster.sailing.id
  key        = var.queue_key
}
output "cluster_id" {
  value = buildkite_cluster.sailing.id
}

output "queue_key" {
  value = buildkite_cluster_queue.kubernetes.key
}

output "agent_token" {
  value     = buildkite_cluster_agent_token.kubernetes.token
  sensitive = true
}

output "performance_pipeline_slug" {
  value = buildkite_pipeline.performance.slug
}
# The pipeline must be linked to the Entire repository provider connection
# (Buildkite Settings > Repository Providers), which the provider can't set —
# create it in the UI by picking the repo from the connection, then
# `tofu import buildkite_pipeline.performance <graphql-id>`.
#
# Step logic lives in performance-step.sh. Buildkite interpolates $VAR in
# pipeline settings, so every $ is doubled to reach the pod untouched.
resource "buildkite_pipeline" "performance" {
  name           = "performance"
  description    = "Dagger CI for the Entire-hosted performance repo"
  repository     = var.performance_repo_url
  default_branch = "main"
  cluster_id     = buildkite_cluster.sailing.id

  steps = yamlencode({
    steps = [{
      label    = ":hammer_and_wrench: dagger check"
      key      = "check"
      agents   = { queue = buildkite_cluster_queue.kubernetes.key }
      commands = [replace(file("${path.module}/performance-step.sh"), "$", "$$")]
      env = {
        DAGGER_VERSION     = var.dagger_version
        DAGGER_ENGINE_HOST = "tcp://dagger-engine.buildkite.svc.cluster.local:1234"
      }
      plugins = [
        "entire",
        {
          kubernetes = {
            podSpec = {
              # Needs bash, curl, git, GNU coreutils (entire plugin requirements).
              containers = [{ image = "ghcr.io/buildkite/agent:4.7.0-ubuntu-24.04" }]
            }
          }
        },
      ]
    }]
  })
}
# TODO(bryan): requires a real Buildkite API token — nothing here runs
# automatically, and no token is stored in this repo.
#
# 1. Create an API access token scoped for Terraform/OpenTofu (write/read
#    pipelines + organization settings + GraphQL):
#      https://buildkite.com/user/api-access-tokens/new?description=opentofu&scopes[]=write_pipelines&scopes[]=write_suites&scopes[]=read_pipelines&scopes[]=read_notification_services&scopes[]=write_notification_services&scopes[]=read_organization_settings&scopes[]=write_organization_settings&scopes[]=graphql
# 2. Export it (never commit it):
#      export BUILDKITE_API_TOKEN=bkua_...
#      export BUILDKITE_ORGANIZATION_SLUG=<your-org-slug>
# 3. just buildkite init
# 4. just buildkite plan    # review: creates 1 cluster, 1 queue, 1 agent token
# 5. just buildkite apply
# 6. just buildkite sync-secret   # SOPS-encrypts the agent token into
#    kubernetes/apps/buildkite/agent-stack-k8s/app/secret-agent-token.sops.yaml
# 7. Add "./secret-agent-token.sops.yaml" to that app's kustomization.yaml
#    resources list, commit, push, `just kube reconcile`.
#
# State (buildkite/terraform.tfstate) contains the agent token in plaintext —
# it's gitignored, not committed. This is a single-user homelab repo, so
# local state is fine; don't copy this as-is into a team setting without
# moving to a remote backend.
provider "buildkite" {}
variable "cluster_name" {
  description = "Buildkite cluster name"
  type        = string
  default     = "Kubernetes"
}

variable "queue_key" {
  description = "Cluster queue key. Must match config.tags (queue=<key>) in kubernetes/apps/buildkite/agent-stack-k8s/app/helmrelease.yaml."
  type        = string
  default     = "kubernetes"
}

variable "performance_repo_url" {
  description = "Native entire:// URL of the performance repo (as shown by the Buildkite Entire connection)"
  type        = string
  default     = "entire://aws-us-east-2.entire.io/et/winstead-io/performance"
}

variable "dagger_version" {
  description = "Dagger CLI version; must match the engine chart in kubernetes/apps/buildkite/dagger-engine"
  type        = string
  default     = "v1.0.0-beta.25"
}
terraform {
  required_version = ">= 1.13.0"

  required_providers {
    buildkite = {
      source  = "buildkite/buildkite"
      version = "1.46.0"
    }
  }
}

